using System;using System.Collections.Generic;using Game.Runtime;using Game.Runtime.TransportPose;using Game.Components;using Unity.Entities;using Unity.Collections;using Unity.Mathematics;using UnityEngine;
internal static class HelipadControl {
 static void Need(bool ok,string label){if(!ok)throw new Exception(label);}
 static void Main(){try{
 var em=new EntityManager();var gridEntity=new Entity{Index=1,Version=1};var boundary=new Entity{Index=2,Version=1};em.ImportEntity(gridEntity);em.ImportEntity(boundary);var grid=new GridConfig{Width=16,Height=16,CellSize=1,Origin=float3.zero};em.AddComponentData(gridEntity,grid);var walk=em.AddBuffer<GridWalkable>(gridEntity);for(int i=0;i<256;i++)walk.Add(new GridWalkable{Value=1});var blocked=new NativeBitArray(256,Allocator.Temp);var occupied=new NativeBitArray(256,Allocator.Temp);em.AddComponentData(gridEntity,new DynamicBlockerComponent{GridSize=256,Blocked=blocked});em.AddComponentData(gridEntity,new DynamicOccupancyComponent{GridSize=256,Occupied=occupied});var rows=em.AddBuffer<BuildingFactionProductionSpawnPointReadModel>(boundary);var helipad=new RuntimeBuildingEntity{Id=17,HasOwnerFaction=true,OwnerFactionId=1,OriginCell=new Vector2Int(4,4),Definition=new RuntimeDefinition{DisplayName="Building_Helipad",FootprintCells=new Vector2Int(2,2)},ProducedUnitSlots=new Entity[1],PendingProductions=new List<SourcePendingProduction>()};var buildings=new Dictionary<int,RuntimeBuildingEntity>{{17,helipad}};rows.Add(new BuildingFactionProductionSpawnPointReadModel{FactionId=1,BuildingId=new FixedString128Bytes("building_helipad"),BuildingRuntimeId=17,SlotIndex=0,Cell=new int2(5,5),WorldPosition=new float3(5.5f,0,5.5f)});var w=new SourceProductionGroundWorld(em,gridEntity,boundary,buildings,new Dictionary<int,PoseGraph>());uint rng=1;bool ok=w.TryResolveAvailableFactionHelipadSpawn(w.SpawnContext,1,null,em,gridEntity,grid,em.GetComponentData<DynamicBlockerComponent>(gridEntity),new int2(1,1),ref rng,out int2 cell,out float3 pos);Need(ok&&cell.Equals(new int2(5,5)),"actual readmodel slot");
 // Block the selected slot with an actual live unit footprint; all fallback grid cells are unwalkable.
 var unit=new Entity{Index=3,Version=1};em.ImportEntity(unit);em.AddComponentData(unit,new UnitGrid{Cell=new int2(5,5)});em.AddComponentData(unit,new UnitFootprint{Size=new int2(1,1)});for(int i=0;i<256;i++)walk[i]=new GridWalkable{Value=0};rng=1;ok=w.TryResolveAvailableFactionHelipadSpawn(w.SpawnContext,1,null,em,gridEntity,grid,em.GetComponentData<DynamicBlockerComponent>(gridEntity),new int2(1,1),ref rng,out cell,out pos);Need(!ok,"occupied slot and unwalkable fallback must fail");em.RemoveComponent<UnitGrid>(unit);helipad.PendingProductions.Add(new SourcePendingProduction{ReservedProductionSlotIndex=0});rng=1;ok=w.TryResolveAvailableFactionHelipadSpawn(w.SpawnContext,1,null,em,gridEntity,grid,em.GetComponentData<DynamicBlockerComponent>(gridEntity),new int2(1,1),ref rng,out cell,out pos);Need(!ok,"reserved slot and unwalkable fallback must fail");helipad.PendingProductions.Clear();rng=1;ok=w.TryResolveAvailableFactionHelipadSpawn(w.SpawnContext,2,null,em,gridEntity,grid,em.GetComponentData<DynamicBlockerComponent>(gridEntity),new int2(1,1),ref rng,out cell,out pos);Need(!ok,"wrong faction must fail");rows.Clear();for(int i=0;i<256;i++)walk[i]=new GridWalkable{Value=1};helipad.Instance=new RuntimeInstance{transform=new RuntimeTransform{position=new Vector3(7.5f,0,7.5f)}};helipad.ProductionSpawnLocalPositions=new[]{new Vector3(0,0,0)};w.ProducerRootFrames=new Dictionary<int,SourceProducerRootFrame>{{17,new SourceProducerRootFrame(new float3(7.5f,0,7.5f),quaternion.identity,1)}};rng=1;ok=w.TryResolveAvailableFactionHelipadSpawn(w.SpawnContext,1,null,em,gridEntity,grid,em.GetComponentData<DynamicBlockerComponent>(gridEntity),new int2(1,1),ref rng,out cell,out pos);Need(ok&&cell.Equals(new int2(7,7)),"managed fallback exact root pose");// Real source root pose must drive managed fallback, including rotation and scale.
 helipad.ProductionSpawnLocalPositions=new[]{new Vector3(1,0,0)};w.ProducerRootFrames=new Dictionary<int,SourceProducerRootFrame>{{17,new SourceProducerRootFrame(new float3(7.5f,0,7.5f),quaternion.RotateY(math.PI/2),2)}};rng=1;ok=w.TryResolveAvailableFactionHelipadSpawn(w.SpawnContext,1,null,em,gridEntity,grid,em.GetComponentData<DynamicBlockerComponent>(gridEntity),new int2(1,1),ref rng,out cell,out pos);Need(ok&&cell.Equals(new int2(7,5)),"rotated and scaled managed root");var sourceBuilding=new RuntimeBuildingEntity{Id=99,HasOwnerFaction=true,OwnerFactionId=1,Instance=new RuntimeInstance(),Definition=new RuntimeDefinition{DisplayName="source",FootprintCells=new Vector2Int(1,1)}};bool failed=false;try{rng=1;w.TryResolveAvailableFactionHelipadSpawn(w.SpawnContext,1,sourceBuilding,em,gridEntity,grid,em.GetComponentData<DynamicBlockerComponent>(gridEntity),new int2(1,1),ref rng,out cell,out pos);}catch(NotSupportedException){failed=true;}Need(failed,"unknown source root must fail closed");w.ProducerRootFrames=new Dictionary<int,SourceProducerRootFrame>{{17,new SourceProducerRootFrame(new float3(7.5f,0,7.5f),quaternion.RotateY(math.PI/2),2)},{99,new SourceProducerRootFrame(new float3(8.5f,0,6.5f),quaternion.identity,1)}};
 // Read-model ordering and distances use source data and stable iteration order.
 var pad2=new RuntimeBuildingEntity{Id=18,HasOwnerFaction=true,OwnerFactionId=1,OriginCell=new Vector2Int(8,4),Definition=new RuntimeDefinition{DisplayName="Building_Helipad",FootprintCells=new Vector2Int(2,2)},ProducedUnitSlots=new Entity[1],PendingProductions=new List<SourcePendingProduction>()};buildings.Add(18,pad2);buildings.Add(99,sourceBuilding);rows.Add(new BuildingFactionProductionSpawnPointReadModel{FactionId=1,BuildingId=new FixedString128Bytes("building_helipad"),BuildingRuntimeId=17,SlotIndex=0,Cell=new int2(4,5),WorldPosition=new float3(4.5f,0,5.5f)});rows.Add(new BuildingFactionProductionSpawnPointReadModel{FactionId=1,BuildingId=new FixedString128Bytes("building_helipad"),BuildingRuntimeId=18,SlotIndex=0,Cell=new int2(8,5),WorldPosition=new float3(8.5f,0,5.5f)});rows.Add(new BuildingFactionProductionSpawnPointReadModel{FactionId=1,BuildingId=new FixedString128Bytes("source"),BuildingRuntimeId=99,SlotIndex=0,Cell=new int2(8,6),WorldPosition=new float3(8.5f,0,6.5f)});rng=1;ok=w.TryResolveAvailableFactionHelipadSpawn(w.SpawnContext,1,sourceBuilding,em,gridEntity,grid,em.GetComponentData<DynamicBlockerComponent>(gridEntity),new int2(1,1),ref rng,out cell,out pos);Need(ok&&cell.Equals(new int2(8,5)),"nearest pad");rows[2]=new BuildingFactionProductionSpawnPointReadModel{FactionId=1,BuildingId=new FixedString128Bytes("source"),BuildingRuntimeId=99,SlotIndex=0,Cell=new int2(6,5),WorldPosition=new float3(6.5f,0,5.5f)};rng=1;ok=w.TryResolveAvailableFactionHelipadSpawn(w.SpawnContext,1,sourceBuilding,em,gridEntity,grid,em.GetComponentData<DynamicBlockerComponent>(gridEntity),new int2(1,1),ref rng,out cell,out pos);Need(ok&&cell.Equals(new int2(4,5)),"tie keeps first");var recent=em.AddBuffer<BuildingRecentSpawnReservation>(boundary);recent.Add(new BuildingRecentSpawnReservation{Cell=new int2(4,5),Size=new int2(1,1),ExpiresAt=100});rng=1;ok=w.TryResolveAvailableFactionHelipadSpawn(w.SpawnContext,1,sourceBuilding,em,gridEntity,grid,em.GetComponentData<DynamicBlockerComponent>(gridEntity),new int2(1,1),ref rng,out cell,out pos);Need(ok&&cell.Equals(new int2(8,5)),"recent reservation avoids first slot");recent.Clear();
 // With no pad slots, actual dynamic occupancy controls the native faction-center fallback.
 rows.Clear();helipad.Instance=null;for(int i=0;i<256;i++)occupied.Set(i,true);rng=1;ok=w.TryResolveAvailableFactionHelipadSpawn(w.SpawnContext,1,null,em,gridEntity,grid,em.GetComponentData<DynamicBlockerComponent>(gridEntity),new int2(1,1),ref rng,out cell,out pos);Need(!ok,"fully occupied fallback");for(int i=0;i<256;i++)occupied.Set(i,false);rng=1;ok=w.TryResolveAvailableFactionHelipadSpawn(w.SpawnContext,1,null,em,gridEntity,grid,em.GetComponentData<DynamicBlockerComponent>(gridEntity),new int2(1,1),ref rng,out cell,out pos);Need(ok,"clear faction fallback");buildings.Clear();rng=1;ok=w.TryResolveAvailableFactionHelipadSpawn(w.SpawnContext,1,null,em,gridEntity,grid,em.GetComponentData<DynamicBlockerComponent>(gridEntity),new int2(1,1),ref rng,out cell,out pos);Need(!ok,"no faction building fallback");
 Console.WriteLine("[SourceHelipadControls] Passed readmodel, managed rotated/scaled root, missing root rejection, nearest/tie, recent reservation, occupancy toggle, occupied/reserved no-fit, wrong faction and no-building fallback; synthetic world only");
 }catch(Exception e){Console.Error.WriteLine(e);Environment.Exit(1);}}
}
